#!/usr/bin/env bash
# tests/feedpost/run.sh <php-binary> <configured-php-src-dir>
#
# Builds feedpost.so against a *configured* php-src tree (php_config.h is
# generated by configure; no phpize/php-dev needed) and runs the
# post_max_size bypass checks (GHSA-2cv3-554h-jpmh):
#
#   sanity : n=5       -> LEN=5, no warning
#   bypass : n=1048576, post_max_size=100K
#            unpatched -> LEN=1048576 (whole body, no warning) = BYPASS
#            patched   -> official "Actual POST length does not match
#                         Content-Length" warning + LEN truncated at the
#                         limit (<= 102400)                        = FIXED
#
# Exit 0 = test ran and classification is unambiguous (either FIXED or
# BYPASS is reported in RESULT:); exit 1 = build/parse failure.
set -euo pipefail

PHP="${1:?usage: run.sh <php-binary> <configured-php-src-dir>}"
SRC="${2:?usage: run.sh <php-binary> <configured-php-src-dir>}"
HERE="$(cd "$(dirname "$0")" && pwd)"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

test -f "$SRC/main/php_config.h" || { echo "FATAL: $SRC is not configured (main/php_config.h missing)"; exit 1; }
ln -s "$SRC/main/php_config.h" "$WORK/config.h"

cc -shared -fPIC -O2 -DHAVE_CONFIG_H=1 -DCOMPILE_DL_FEEDPOST=1 \
  -I"$WORK" -I"$SRC" -I"$SRC/main" -I"$SRC/Zend" -I"$SRC/TSRM" \
  -I"$SRC/ext/session" \
  "$HERE/feedpost.c" -o "$WORK/feedpost.so" 2>"$WORK/build.log" || {
    echo "FATAL: feedpost.so build failed"; cat "$WORK/build.log"; exit 1; }

EXT=(-d "extension=$WORK/feedpost.so" -d "disable_functions=")

echo "== sanity (n=5) =="
out="$("$PHP" "${EXT[@]}" -d post_max_size=100K "$HERE/feedtest.php" 5 2>&1)"
echo "$out"
echo "$out" | grep -q '^LEN=5$' || { echo "FAIL: sanity run did not print LEN=5"; exit 1; }
echo "$out" | grep -qi 'warning' && { echo "FAIL: unexpected warning on sanity run"; exit 1; }

echo "== big body (n=1048576, post_max_size=100K) =="
out="$("$PHP" "${EXT[@]}" -d post_max_size=100K "$HERE/feedtest.php" 1048576 2>&1)"
echo "$out"
len="$(echo "$out" | sed -n 's/^LEN=//p')"
[ -n "$len" ] || { echo "FAIL: no LEN= line"; exit 1; }

if echo "$out" | grep -q "Actual POST length does not match Content-Length"; then
  if [ "$len" -le 102400 ] 2>/dev/null; then
    echo "RESULT: FIXED (warning emitted, truncated to $len <= 102400)"
  else
    echo "FAIL: warning emitted but LEN=$len exceeds post_max_size"; exit 1
  fi
else
  if [ "$len" = 1048576 ]; then
    echo "RESULT: BYPASS (full body accepted silently — post_max_size not enforced)"
  else
    echo "FAIL: no warning and LEN=$len (expected 1048576 or a truncation)"; exit 1
  fi
fi
